import json,io
v=json.load(io.open('verification/verdict_judge.json',encoding='utf-8'))
cases=v['cases']
print(type(cases), len(cases))
def eps(c):
    steps=c.get('steps') if isinstance(c,dict) else None
    out=set()
    if isinstance(steps,dict):
        for s in steps.values():
            out.add(s.get('endpoint'))
    return out
dropped=[]; ruled=[]; failed=[]
items = cases.items() if isinstance(cases,dict) else [(c.get('id','?'),c) for c in cases]
for k,c in items:
    ver=c.get('verdict') or c.get('status')
    if ver=='dropped': dropped.append((k,sorted(x for x in eps(c) if x), c.get('reason') or c.get('why')))
    elif ver in ('fail','error'): failed.append((k,c))
    elif ver=='migration-change' or ver=='ruled': ruled.append((k,sorted(x for x in eps(c) if x)))
print('dropped',len(dropped))
for d in dropped: print('  ',d)
print('ruled',len(ruled))
for d in ruled: print('  ',d)
print('failed',len(failed))
print(v['summary'] if isinstance(v['summary'],str) else json.dumps(v['summary'],ensure_ascii=False)[:800])
EOF

